const PHOTO_ALIAS20={'save-':'save','natsumi-':'natsumi','chira_junior':'chira-junior','not me':'not-me','y`':'y','ws`':'ws','no[o]ne-':'noone','davai lama':'davai-lama'};
function bio20(p){return !p.fiction?BIO20[nameKey4(p.name)]:null;}
function photo20(p){let key=p.name.toLowerCase();return !p.fiction?PLAYER_PHOTOS_V2[PHOTO_ALIAS20[key]||key]:null;}
function portrait20(p,large=false){let src=photo20(p);return `<span class="portrait20 ${large?'portrait-large20':''}">${src?`<img src="${esc(src)}" alt="${esc(p.name)}" ${large?'':'loading="lazy"'} referrerpolicy="no-referrer" onerror="this.hidden=true;this.nextElementSibling.hidden=false">`:''}<span ${src?'hidden':''} class="portrait-placeholder20"><svg viewBox="0 0 100 110" aria-hidden="true"><circle cx="50" cy="32" r="20"/><path d="M12 110V92c0-23 17-37 38-37s38 14 38 37v18z"/></svg>${large?'<small>Фотография недоступна</small>':''}</span></span>`;}
// Match abbreviations from Liquipedia; edited/generated club tags stay career-owned.
const CLUB_TAGS20=['XG','TSpirit','BB','Yandex','OG','Tidebd','PTime','LGD','PARI','NAVI','Aurora','1w','GL','Xipto','CvS','Liquid'];
function clubTag20(t){let seed=SEED_TEAMS[t.id];return seed&&t.name===seed[0]&&t.short===seed[1]?CLUB_TAGS20[t.id]:t.short;}
function tag20(p){let t=p.team==null?null:S.teams[p.team];return t?`[${esc(clubTag20(t))}] `:'';}
function playerLink20(p){return `<button class="player-link20" onclick="profile(${p.id})">${tag20(p)}${esc(p.name)}</button>`;}
function year20(day){return new Date(BASE_DATE_V1+day*86400000).getUTCFullYear();}
function awardDay20(e){return e.completedDay20??e.day+(e.duration||1)-1;}
const finishCalendarBefore20=finishCalendar13;finishCalendar13=function(e){e.completedDay20=Math.max(S.day,e.day+(e.duration||1)-1);return finishCalendarBefore20(e);};
let awardYear20=null,awardClub20=null,playerSearch20='',playerClub20='',playerRole20='',selectedPlayer20=null,playerBack20='players';
const homePage20=PAGES.find(p=>p[0]==='home');homePage20[2]='Главная';
PAGES.splice(1,0,['match','▷','Матч-центр']);
PAGES.splice(PAGES.findIndex(p=>p[0]==='squad')+1,0,['players','◎','Игроки']);
PAGES.splice(PAGES.findIndex(p=>p[0]==='finance'),0,['trophies','🏆','Зал наград']);
function wins20(club=S.club,year=awardYear20??year20(S.day)){return S.events.filter(e=>e.done&&!e.practice13&&(e.champion===club||e.champion==null&&club===S.club&&e.place===1)&&year20(awardDay20(e))===+year).sort((a,b)=>b.day-a.day);}
function trophiesView20(){let club=awardClub20??S.club,t=S.teams[club]||my(),years=[...new Set([year20(S.day),...S.events.filter(e=>e.done).map(e=>year20(awardDay20(e)))])].sort((a,b)=>b-a),year=awardYear20??year20(S.day),wins=wins20(club,year);return head('ДОСТИЖЕНИЯ КЛУБА','Зал наград','Титулы, завоёванные в этой карьере.')+`<div class="filters"><select aria-label="Команда" onchange="awardClub20=+this.value;render()">${S.teams.map(t=>`<option value="${t.id}" ${club===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><select aria-label="Год наград" onchange="awardYear20=+this.value;render()">${years.map(y=>`<option ${year===y?'selected':''}>${y}</option>`).join('')}</select></div><section class="panel trophy-summary20">${clubAvatar12(t)}<div><span class="eyebrow">${year} / ${esc(t.name)}</span><h2>${wins.length} ${wins.length===1?'титул':'титулов'}</h2><p>Победы в турнирах за выбранный календарный год</p></div></section>${wins.length?'<div class="trophy-grid20">'+wins.map(e=>`<article class="panel trophy-card20"><div class="trophy-icon20">🏆</div><span class="eyebrow">ЧЕМПИОН</span><h2>${esc(e.name)}</h2><p>${date(awardDay20(e))}</p><div class="hero-foot"><span>Фонд <b>${cash(e.pool)}</b></span>${btn('Турнир →',`showBracket(${e.id})`)}</div></article>`).join('')+'</div>':`<section class="panel empty"><div class="trophy-icon20">🏆</div><h2>Трофеи впереди</h2><p>У ${esc(t.name)} пока нет побед за ${year} год. Здесь появится каждый выигранный турнир.</p>${btn('К календарю',"go('calendar')",true)}</section>`}`;}
function playerMatches20(){return S.players.filter(p=>(!playerSearch20||p.name.toLowerCase().includes(playerSearch20.toLowerCase())||((bio20(p)?.first||'')+' '+(bio20(p)?.last||'')).toLowerCase().includes(playerSearch20.toLowerCase()))&&(playerClub20===''||String(p.team)===playerClub20)&&(playerRole20===''||p.role===+playerRole20)).sort((a,b)=>b.skill-a.skill);}
function playerCards20(){let ps=playerMatches20();return ps.map(p=>`<article class="panel person-card20"><button class="portrait-button20" aria-label="Профиль ${esc(p.name)}" onclick="profile(${p.id})">${portrait20(p)}</button><div class="person-content20"><span class="eyebrow">${p.retired?'ЗАВЕРШИЛ КАРЬЕРУ':ROLES[p.role]}</span><h2>${playerLink20(p)}</h2><p>${bio20(p)?esc(bio20(p).first+' '+bio20(p).last):'Вымышленный игрок'}</p><div class="person-meta20"><span>${esc(bio20(p)?.country||'—')}</span><b class="rating">${Math.round(p.skill)}</b></div>${btn('Открыть профиль →',`profile(${p.id})`)}</div></article>`).join('')||'<section class="panel empty">Игроки не найдены. Измени фильтры.</section>';}
function playersView20(){return head('БАЗА ИГРОКОВ','Игроки','Биографии, форма и стоимость каждого игрока.')+`<div class="filters"><input id="playerSearch20" aria-label="Поиск игрока" placeholder="Ник, имя или фамилия…" value="${esc(playerSearch20)}" oninput="playerSearch20=this.value;document.getElementById('playerGrid20').innerHTML=playerCards20()"><select aria-label="Команда игрока" onchange="playerClub20=this.value;render()"><option value="">Все команды</option><option value="null" ${playerClub20==='null'?'selected':''}>Свободные агенты / архив</option>${S.teams.map(t=>`<option value="${t.id}" ${playerClub20===String(t.id)?'selected':''}>${esc(t.name)}</option>`).join('')}</select><select aria-label="Позиция игрока" onchange="playerRole20=this.value;render()"><option value="">Все позиции</option>${ROLES.map((r,i)=>`<option value="${i}" ${playerRole20===String(i)?'selected':''}>${r}</option>`).join('')}</select></div><div class="people-grid20" id="playerGrid20">${playerCards20()}</div>`;}
profile=function(id){if(!S.players[id])return;if(page!=='player')playerBack20=page;selectedPlayer20=id;closeModal();go('player');};
function playerView20(){let p=S.players[selectedPlayer20];if(!p)return playersView20();let b=bio20(p),t=S.teams[p.team],region=t?({CN:'Китай',EEU:'Восточная Европа',EU:'Европа',INT:'Международный',SEA:'Юго-Восточная Азия',NA:'Северная Америка',SA:'Южная Америка'}[t.region]||t.region):'Свободный агент',own=p.team===S.club&&!p.retired;return `<button class="back20" onclick="go('${playerBack20==='player'?'players':playerBack20}')">← Назад</button>`+head('ЛИЧНОЕ ДЕЛО','Информация об игроке',p.retired?'Завершил карьеру · '+date(p.retiredDay):t?.name||'Свободный агент')+`<div class="profile-layout20"><section class="panel profile-photo20">${portrait20(p,true)}<div class="profile-nick20">${tag20(p)}${esc(p.name)}</div></section><section class="panel dossier20"><h2>Личные данные</h2><dl><div><dt>Имя</dt><dd>${esc(b?.first||'—')}</dd></div><div><dt>Фамилия</dt><dd>${esc(b?.last||'—')}</dd></div><div><dt>Страна</dt><dd>${esc(b?.country||'—')}</dd></div><div><dt>Позиция</dt><dd>${p.role+1} · ${ROLES[p.role]}</dd></div><div><dt>Регион выступлений</dt><dd>${p.retired?'Архив':esc(region)}</dd></div></dl>${b?`<a class="source-link20" href="${esc(b.source)}" target="_blank" rel="noopener">Liquipedia · источник биографии ↗</a>`:'<p class="sub">Биография не заполнена.</p>'}${photo20(p)?'<p class="sub">Фото: <a href="https://cyberscore.live/en/players/" target="_blank" rel="noopener">CyberScore</a></p>':''}</section><section class="panel player-form20"><h2>Игровые показатели</h2><div class="overall20"><span>Рейтинг</span><strong>${Math.round(p.skill)}</strong><small>OVR / 100</small></div>${bar('Форма',p.form)}<div class="price20"><span>Стоимость</span><strong>${cash(value(p))}</strong></div><p class="sub">Рейтинг, форма и стоимость — показатели этой карьеры.</p></section></div><section class="panel management20"><div><h2>${p.retired?'ЗАВЕРШИЛ КАРЬЕРУ':'Контракт и действия'}</h2><p>${p.retired?'Последний клуб: '+esc(S.teams[p.retiredFromTeam]?.name||'—'):p.team==null?'Свободный агент':`${esc(t.name)} · ${p.active?'Основной состав':'Резерв'} · ${p.contract} дней · ${cash(p.salary)}/нед.`}</p></div><div class="actions">${own?`${btn('Продлить · '+cash(p.salary*3),`renew(${p.id})`,false,S.budget<p.salary*3)}${!p.active?btn('В основу',`promote(${p.id})`,true,locked())+btn('Освободить контракт',`sell(${p.id})`,false,locked()):''}${btn('Завершить карьеру игрока',`askRetirePlayer(${p.id})`,false,locked())}${p.fiction?btn('Изменить никнейм',`renamePlayer12(${p.id})`):''}`:!p.retired?btn('Предложить контракт',`offer(${p.id})`,true,locked()):''}</div></section>`;}
playerTable=function(ps,actions=true){return `<div class="table-wrap"><table><thead><tr><th>ИГРОК</th><th>ПОЗИЦИЯ</th><th>РЕЙТИНГ</th><th>ФОРМА</th><th>ЭНЕРГИЯ</th>${actions?'<th>КОНТРАКТ</th><th></th>':''}</tr></thead><tbody>${ps.map(p=>`<tr><td><span class="player-cell20">${portrait20(p)}${playerLink20(p)}</span>${p.fiction?'<span class="sub">Вымышленный игрок</span>':''}</td><td>${ROLES[p.role]}</td><td><span class="rating">${Math.round(p.skill)}</span></td><td>${Math.round(p.form)}</td><td class="green">${Math.round(100-p.fatigue)}%</td>${actions?`<td>${cash(p.salary)}/нед.<span class="sub">${p.contract} дней</span></td><td>${btn('Профиль →',`profile(${p.id})`)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;};
function agenda20(){let events=S.events.filter(e=>!e.done).slice(0,4);return `<section class="panel agenda20"><h2>Ближайшие турниры</h2>${events.map(e=>`<button class="agenda-item20" onclick="go('calendar')"><span class="agenda-date20">${new Date(BASE_DATE_V1+e.day*86400000).getUTCDate()}<small>${new Date(BASE_DATE_V1+e.day*86400000).toLocaleDateString('ru-RU',{month:'short',timeZone:'UTC'})}</small></span><span><b>${esc(e.name)}</b><small>${cash(e.pool)} · ${e.duration||1} дн.</small></span><span>↗</span></button>`).join('')}</section>`;}
home=function(){let e=nextEvent(),a=S.active,opp=a?S.teams[a.opponent]:null;return head('ANCIENT MANAGER / 2.0',esc(my().name),'Твой клуб. Следующий вызов. История побед.',`<span class="tag">СЕЗОН ${year20(S.day)}</span>`)+`<div class="stats">${stat('Бюджет',cash(S.budget),'Средства клуба')}${stat('Рейтинг состава',Math.round(strength()),'Командная сила')}${stat('Победы / поражения',S.wins+' / '+S.losses,'Сыгранные серии')}${stat('Трофеи за год',wins20(S.club,year20(S.day)).length,'Зал наград · '+year20(S.day))}</div><div class="dashboard20"><div class="dashboard-main20"><section class="panel hero feature20"><div class="section-head"><span class="eyebrow">${a?'ТЕКУЩИЙ ТУРНИР':'СЛЕДУЮЩИЙ ТУРНИР'}</span><span class="tag dim">${e?date(e.day):'Календарь'}</span></div><h2>${esc(e?.name||'Сезон продолжается')}</h2><div class="matchup">${teamDisplay(my())}<div class="versus"><strong>${a?a.score.join(' : '):'VS'}</strong>${a?'Матч-центр':'Соперник после жеребьёвки'}</div>${opp?teamDisplay(opp):'<div class="team-display"><div class="unknown-crest20">?</div><span>Будущий соперник</span></div>'}</div><div class="hero-foot"><span>Призовой фонд <b>${cash(e?.pool||0)}</b></span>${btn(a?'В матч-центр →':e?.day<=S.day?'Начать турнир →':'Подготовить команду →',a?"go('match')":e?.day<=S.day?'startEvent()':"go('tactics')",true)}</div></section><section class="panel"><div class="section-head"><h2>Текущая команда</h2>${btn('Состав →',"go('squad')")}</div>${playerTable(roster(),false)}</section>${S.active?`<section class="panel"><div class="section-head"><h2>Турнирный центр</h2>${btn('Группы и сетка →',`showBracket(${S.active.event})`)}</div><p>${esc(S.active.stage||'Турнир идёт')} · Счёт серии ${S.active.score.join(' : ')}</p></section>`:''}</div><div class="dashboard-side20">${agenda20()}<section class="panel"><h2>Подготовка команды</h2>${bar('Сыгранность',S.chem)}${bar('Игровая форма',metric('form'))}${bar('Энергия',100-metric('fatigue'))}${btn('Тренировки →',"go('tactics')")}</section><section class="panel"><h2>Новости клуба</h2>${S.news.slice(0,3).map(n=>`<div class="news"><small>${date(n.day)}</small>${esc(n.text)}</div>`).join('')}</section></div></div>${typeof tiBanner==='function'?tiBanner():''}${skipPanel12()}`;};
const matchPrevious20=matchView;matchView=function(){if(S.active)return matchPrevious20();let e=nextEvent();return head('МАТЧ-ЦЕНТР','Следующая серия впереди','Здесь доступны симуляция, тренерский режим и отчёты по матчам.')+`<div class="columns"><section class="panel"><h2>${esc(e?.name||'Турниры сезона')}</h2><p>${e?date(e.day):''}</p>${btn(e?.day<=S.day?'Начать турнир →':'К календарю →',e?.day<=S.day?'startEvent()':"go('calendar')",true)}</section><section class="panel"><h2>Последний результат</h2>${S.history.length?`<p>${esc(S.history[0].event)} · ${S.history[0].score.join(' : ')}</p>${btn('Отчёт по картам','report(0)')}`:'<p>Сыграй первую серию — её результат появится здесь.</p>'}</section></div>`+history();};
const marketPrevious20=market;market=function(){let html=marketPrevious20();for(let p of S.players){let needle='<h3>'+esc(p.name)+'</h3>';if(html.includes(needle))html=html.replace(needle,`<div class="market-identity20">${portrait20(p)}<h3>${playerLink20(p)}</h3></div>`);}return html;};
const clubsPrevious20=clubs;clubs=function(){let html=clubsPrevious20();for(let p of S.players)html=html.replaceAll('<b>'+esc(p.name)+'</b>',playerLink20(p));return html;};
const renderPrevious20=render;render=function(){renderPrevious20();if(S&&typeof page==='string'){$('crumb').textContent=page==='player'?'Профиль игрока':PAGES.find(p=>p[0]===page)?.[2]||'Главная';}};
const settingsPrevious20=settings;settings=function(){return settingsPrevious20();};
